'use strict';
(() => {
const $ = s => document.querySelector(s), KEY='scikit-studio-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let course,state,activeTest=null,timer=null;
const fresh=()=>({edition:1,completed:[],reviewed:[],tests:{},rubrics:{},notes:{},days:[],attempts:{},last:1});
let storageAvailable=true;
try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{state=fresh();storageAvailable=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;toast('Browser storage is unavailable. Export progress before leaving.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const moduleBy=id=>course.modules.find(m=>m.id===Number(id));
const lessonBy=id=>course.lessons.find(l=>l.id===Number(id));
const lessonDone=id=>state.completed.includes(id);
const projectPass=id=>(state.rubrics[id]?.scores||[]).length===4&&state.rubrics[id].scores.every(n=>n>=2);
const modulePass=id=>Number(state.tests[id]?.score)>=80&&state.tests[id]?.confirmed!==false&&projectPass(id);
const unlocked=id=>Number(id)===11||Number(id)===1||Array.from({length:Number(id)-1},(_,i)=>i+1).every(modulePass);
const totalDone=()=>state.completed.filter(n=>n<=38).length;
const symbols=['✿','▦','◈','✧','◒','♧','✦','☷','▣','★','✺'];
function sidebar(active){$('#side-content').innerHTML=`<div class="nav-label">YOUR SPACE</div>${[['home','⌂','Overview'],['curriculum','▦','Course map'],['challenge','⚑','14-day challenge'],['glossary','Aa','Glossary'],['resources','▤','Practice & resources']].map(([route,icon,name])=>`<a class="nav-item ${active===route?'active':''}" href="#${route}" ${active===route?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}${route==='curriculum'?'<span class="count">47</span>':''}</a>`).join('')}<div class="sidebar-mini"><p><strong>${totalDone()} / 38</strong> core lessons completed</p><div class="progress-track" role="progressbar" aria-label="Core lesson completion" aria-valuemin="0" aria-valuemax="38" aria-valuenow="${totalDone()}"><span style="width:${totalDone()/38*100}%"></span></div><p style="margin-top:12px">${course.modules.slice(0,10).filter(m=>modulePass(m.id)).length} / 10 modules passed</p></div><a class="nav-item" href="https://github.com/Momore55/scikit-learn-course" target="_blank" rel="noopener"><span class="nav-icon">⌘</span>Source code ↗</a>`;}
const badge=m=>`<span class="badge ${m.optional?'optional':unlocked(m.id)?'':'locked'}">${m.optional?'Optional':modulePass(m.id)?'Passed':unlocked(m.id)?'Ready to learn':'Locked'}</span>`;
function moduleCard(m){const count=state.completed.filter(n=>n>=m.start&&n<=m.end).length;return `<a class="module-card ${unlocked(m.id)&&!m.optional&&!modulePass(m.id)?'current':''}" href="#module/${m.id}"><div class="module-card-top"><span class="module-symbol">${symbols[m.id-1]}</span>${badge(m)}</div><div class="module-label">MODULE ${String(m.id).padStart(2,'0')}</div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="card-bottom"><span>${m.end-m.start+1} lessons · ${m.hours} hrs</span><span>${count}/${m.end-m.start+1} complete</span></div></a>`;}
function art(){return `<div class="hero-art" aria-hidden="true"><div class="halo"></div><div class="art-star">✦</div><div class="art-star two">✦</div><div class="bot"><div class="face"><span class="eye"></span><span class="eye"></span><span class="smile"></span></div></div><div class="float-tile one">{ }</div><div class="float-tile two">✧</div><div class="float-tile three"><span>✓</span> A little better, every day</div></div>`;}
function nextLesson(){return course.lessons.find(l=>l.id===state.last&&unlocked(l.module)&&!lessonDone(l.id))||course.lessons.find(l=>l.id<=38&&unlocked(l.module)&&!lessonDone(l.id))||course.lessons.find(l=>unlocked(l.module))||course.lessons[0];}
function overview(){const next=nextLesson(),m=moduleBy(next.module);return `<div class="welcome-row"><div><h1>Hey, curious mind <span aria-hidden="true">✦</span></h1><p>A fresh idea. A little practice. Your next small win.</p></div><span class="pill">✿ Your own pace. Your own path.</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">GROW YOUR MACHINE LEARNING SKILLS</div><h2>Small steps.<br>Big model energy.</h2><p>Make scikit-learn click, one clear explanation and hands-on project at a time.</p><a class="btn" href="#lesson/${next.id}">${totalDone()?'Keep learning':'Let’s start learning'} <span>✦</span></a></div>${art()}</section><div class="stats"><div class="stat"><div class="stat-icon">▤</div><div><strong>${totalDone()}<small> / 38</small></strong><span>Core lessons completed</span></div></div><div class="stat"><div class="stat-icon">✧</div><div><strong>${course.modules.slice(0,10).filter(m=>modulePass(m.id)).length}<small> / 10</small></strong><span>Modules passed</span></div></div><div class="stat"><div class="stat-icon">⚑</div><div><strong>${state.days.length}<small> / 14</small></strong><span>Challenge days completed</span></div></div></div><div class="two-col"><section class="panel"><div class="eyebrow">YOUR NEXT LITTLE WIN</div><h2>${esc(m.title)}</h2>${course.lessons.filter(l=>l.module===m.id).slice(0,3).map(l=>`<a class="next-lesson" href="#lesson/${l.id}"><span class="lesson-number">${lessonDone(l.id)?'✓':String(l.id).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>Chapter ${l.id} · explanation, example & practice</p></div><span class="mini-check">${lessonDone(l.id)?'✓':'○'}</span></a>`).join('')}</section><section class="panel purple"><span class="challenge-art" aria-hidden="true">⚑</span><h2 style="margin-top:18px">Learn it. Then build it.</h2><p class="small-copy">Your 14-day challenge turns the course into independent projects. Two to three hours, one focused problem, one small win.</p><a class="btn light small" href="#challenge">Explore the challenge</a></section></div><div class="section-head"><div><h2>Your learning path</h2><p>A thoughtful route from first model to independent work.</p></div><a class="text-link" href="#curriculum">See all modules</a></div><div class="module-grid">${course.modules.slice(0,3).map(moduleCard).join('')}</div>`;}
function curriculum(){return `<div class="page-intro"><div class="eyebrow">YOUR LEARNING PATH</div><h1>Make room for<br>your next big idea.</h1><p>38 core lessons. Ten modules. Practice at every stop. Pass each module’s test and project self-review to unlock the next.</p><span class="pill">112–165 core hours · provisional estimate</span></div><div class="module-grid">${course.modules.slice(0,10).map(moduleCard).join('')}</div><div class="section-head"><div><h2>A little extra curiosity</h2><p>Nine optional labs. Explore whenever you’re ready.</p></div></div>${moduleCard(course.modules[10])}`;}
function modulePage(m){if(!m)return missing();const passed=modulePass(m.id);return `<div class="page-intro"><div class="eyebrow">MODULE ${m.id} · ${m.hours} ESTIMATED HOURS</div><h1>${esc(m.title)}</h1><p>${esc(m.description)}</p>${badge(m)}</div>${!unlocked(m.id)?`<div class="callout yellow"><strong>Your next stepping stone</strong><p>You can review this module’s outline now. Pass the previous core modules’ tests and project self-reviews to open its lessons.</p><a class="text-link" href="#module/${m.id-1}">Review the previous module</a></div>`:''}<div class="lesson-list">${course.lessons.filter(l=>l.module===m.id).map(l=>`<a href="#lesson/${l.id}"><span class="lesson-number">${lessonDone(l.id)?'✓':l.id}</span><div><h3>${esc(l.title)}</h3><p>${l.code?'Executed example · notebook · practice':'Writing exercise · rubric-based review'}</p></div></a>`).join('')}</div>${m.optional?`<div class="callout purple"><p>Each extension has a five-question quiz and its own lab. Open a lesson to find both. Extensions do not gate your core course.</p></div>`:`<div class="section-head"><h2>Bring it all together</h2></div><div class="two-col"><section class="panel tint"><div class="eyebrow">MODULE TEST</div><h3>${m.id===10?'40':'20'} questions. One good check-in.</h3><p class="small-copy">80% to pass. Review explanations after submitting, then return to the lessons you need.</p><a class="btn" href="#test/${m.id}">${state.tests[m.id]?'Review or retake':'Start the test'}</a></section><section class="panel yellow"><div class="eyebrow">HANDS-ON PROJECT</div><h3>${esc(m.project.title)}</h3><p class="small-copy">${esc(m.project.dataset)} · Submit your evidence as a local reference, then score your work against four criteria.</p><a class="btn light" href="#project/${m.id}">Open project brief</a></section></div>${passed?'<div class="completion-box">✦ Module passed. Your next module is ready.</div>':''}`}`;}
function getQuiz(l){const bank=moduleBy(l.module).questions;return bank.filter(q=>q.chapter===l.id).slice(0,5);}
function questionHTML(q,index,prefix='q',review=null){const written=q.type==='Written explanation';const chosen=review?.answers?.[index];const result=review?(written?`<div class="feedback"><strong>Compare your explanation.</strong> ${esc(q.explanation)}<p>Self-review: 0 = missing or incorrect; 1 = correct idea with a clear explanation. This written answer is not automatically graded.</p><label>My written-answer score <select data-written-score="${index}" aria-label="Written answer ${index+1} self-score"><option value="">Choose a score</option><option value="0" ${review.written?.[index]===0?'selected':''}>0 / 1</option><option value="1" ${review.written?.[index]===1?'selected':''}>1 / 1</option></select></label></div>`:`<div class="feedback ${chosen===q.correct?'':'bad'}"><strong>${chosen===q.correct?'That’s it.':'Let’s revisit this.'}</strong> ${esc(q.explanation)} <a class="text-link" href="#lesson/${q.chapter}">Review Chapter ${q.chapter}</a></div>`):`<div id="feedback-${prefix}${index}"></div>`;return `<div class="quiz-card"><fieldset><legend><span class="eyebrow">${index+1} · ${esc(q.type)}</span>${esc(q.prompt)}</legend>${q.code?`<details class="solution"><summary>Code for this question</summary><div class="code-wrap"><pre><code>${esc(q.code)}</code></pre></div></details>`:''}${written?`<label class="sr-only" for="${prefix}${index}">Your written explanation</label><textarea class="notes-area" name="${prefix}${index}" id="${prefix}${index}" placeholder="Explain the idea in your own words…" ${review?'readonly':''}>${esc(chosen||'')}</textarea>`:q.options.map((o,j)=>`<label class="option"><input type="radio" name="${prefix}${index}" value="${j}" ${chosen===j?'checked':''} ${review?'disabled':''}><span>${esc(o)}</span></label>`).join('')}${result}</fieldset></div>`;}

function lessonPage(l){if(!l)return missing();const m=moduleBy(l.module);if(!unlocked(l.module))return locked(m);state.last=l.id;save();const quiz=getQuiz(l);return `<div class="page-intro"><a class="text-link" href="#module/${m.id}">Module ${m.id}: ${esc(m.title)}</a><div class="eyebrow" style="margin-top:24px">CHAPTER ${l.id} ${m.optional?'· OPTIONAL LAB':''}</div><h1>${esc(l.title)}</h1><p>${esc(l.goal)}</p><div class="tools-row"><a class="btn light small" href="notebooks/chapter-${String(l.id).padStart(2,'0')}.ipynb" download>Download notebook</a><button class="btn light small" data-action="bookmark" data-id="${l.id}">Save my place</button><button class="btn light small" data-action="print">Print lesson</button></div></div><div class="lesson-grid"><article class="lesson-content"><section id="idea"><div class="callout"><strong>Before you begin</strong><p>${l.id===1?'This is a follow-along preview. The vocabulary and mathematics are unpacked in later lessons.':`Use earlier chapters as prerequisites. If a shape, method, or evaluation role is unfamiliar, return to its glossary entry before continuing.`}</p></div><h2>The big idea</h2><p>${esc(l.idea)}</p><div class="callout purple"><strong>Think of it this way</strong><p>${esc(l.analogy)}</p></div><h2>The plan</h2><ol><li>Understand the idea and the information each step may use.</li><li>${l.code?'Run the example from top to bottom and inspect its output.':'Work through the report structure using an earlier project.'}</li><li>Explain the result, try the exercise, then check your understanding.</li></ol></section><section id="steps"><h2>Step by step</h2><p>${esc(l.walk)}</p>${l.code?`<div class="code-wrap"><div class="code-head"><span>PYTHON · STANDALONE EXAMPLE</span><button class="copy-code" data-action="copy" data-id="${l.id}">Copy code</button></div><pre><code>${esc(l.code)}</code></pre></div><div class="output"><div class="output-label">OUTPUT · EXECUTED IN THE COURSE ENVIRONMENT</div><pre>${esc(l.output)}</pre></div>${l.image?`<img class="lesson-image" src="${l.image}" alt="Scatter plot showing study hours and scores increasing together in five constructed examples">`:''}${l.warnings?`<details class="solution"><summary>Execution notes</summary><pre>${esc(l.warnings)}</pre></details>`:''}<details class="line-notes"><summary>Read the code, line by line</summary>${l.notes.map(n=>`<div class="line-note"><span class="line-num">${n.line}</span><div><code>${esc(n.code)}</code><p>${esc(n.note)}</p></div></div>`).join('')}</details>`:''}<h2>Reading ${l.code?'the output':'the result'}</h2><p>${esc(l.reading)}</p><div class="callout yellow"><strong>A common mistake to avoid</strong><p>${esc(l.wrong)} This is not a valid assumption. ${esc(l.answer)}</p></div></section><section id="vocabulary"><h2>Words worth knowing</h2><div class="definition-grid">${l.terms.map(t=>`<div class="definition"><strong>${esc(t.term)}</strong><p>${esc(t.meaning)}</p><a class="text-link" href="#glossary/${encodeURIComponent(t.term)}">Find in glossary</a></div>`).join('')}</div></section><section id="errors"><h2>If something goes wrong</h2><div class="output"><div class="output-label">ERROR OR REVIEW SIGNAL</div><pre>${esc(l.error)}</pre></div><p>${esc(l.fix)}</p></section><section id="practice"><h2>Your turn. Make it yours.</h2><div class="callout"><p>${esc(l.task)}</p></div><details class="solution"><summary>A hint to get you moving</summary><p>Start with the example’s input contract. Change one thing, inspect shapes and outputs, and explain whether you are illustrating behavior or evaluating unseen performance.</p></details><details class="solution"><summary>Reveal the solution approach</summary><p>${esc(l.solution)}</p></details><h2>Check your understanding</h2><form id="chapter-quiz" data-lesson="${l.id}">${quiz.map((q,i)=>questionHTML(q,i,'cq')).join('')}<button class="btn" type="submit">Check my answers</button><div id="chapter-result" role="status"></div></form></section><section id="finish"><h2>What you did</h2><p>You worked through ${esc(l.title.toLowerCase())}, inspected its assumptions, and connected the result to a practical decision. Use your own words to explain the example before marking the lesson complete.</p><div class="checklist"><label><input type="checkbox" class="completion-check"> I can explain the main idea and new vocabulary.</label><label><input type="checkbox" class="completion-check"> ${l.code?'I ran the example and can interpret its output.':'I completed the written practice and reviewed the rubric.'}</label><label><input type="checkbox" class="completion-check"> I attempted the exercise and checked my reasoning.</label></div><h3 style="margin-top:24px">A note to your future self</h3><label class="sr-only" for="lesson-notes">Your personal lesson notes</label><textarea class="notes-area" id="lesson-notes" data-id="${l.id}" placeholder="What clicked? What would you like to revisit?">${esc(state.notes[l.id]||'')}</textarea><p class="small-copy">Notes save in this browser. Export progress from Resources to move them.</p><p><a class="text-link" href="${l.docs}" target="_blank" rel="noopener">Read the official scikit-learn 1.8 guide ↗</a></p><div class="lesson-actions"><button class="btn lime" data-action="complete" data-id="${l.id}">${lessonDone(l.id)?'✓ Lesson completed':'Mark lesson complete'}</button>${m.optional?`<a class="btn purple" href="#test/11/${l.id}">Take the five-question quiz</a>`:l.id<m.end?`<a class="btn light" href="#lesson/${l.id+1}">Next lesson</a>`:`<a class="btn light" href="#module/${m.id}">Module test & project</a>`}</div>${m.optional?`<div class="callout purple"><strong>Your extension lab</strong><p>${esc(l.task)}</p><a class="text-link" href="#project/11/${l.id}">Open the lab rubric</a></div>`:''}</section></article><nav class="lesson-toc" aria-label="On this page"><strong>ON THIS PAGE</strong>${[['idea','The big idea'],['steps','Step by step'],['vocabulary','Vocabulary'],['errors','Troubleshooting'],['practice','Your turn'],['finish','Finish & reflect']].map(([id,title])=>`<a href="#" data-scroll="${id}">${title}</a>`).join('')}</nav></div>`;}
function locked(m){return `<div class="page-intro"><div class="eyebrow">A STEP AT A TIME</div><h1>This lesson is up next.</h1><p>Pass the earlier modules’ tests and project self-reviews to unlock Module ${m.id}. You can still read its outline.</p><a class="btn" href="#module/${m.id}">See module outline</a></div>`;}
const criteria=[['Correctness','The code runs from top to bottom, outputs match the task, and checks expose invalid inputs.'],['Honest evaluation','Use an appropriate baseline, split, metric, and leakage-safe workflow. For audits or unsupervised work, explain the relevant evaluation limits.'],['Clear explanation','Name units and partitions, interpret results, and state limitations without unsupported claims.'],['Reproducibility','Record source/access instructions, versions, seeds, execution steps, and example inputs where applicable.']];
function projectPage(m,lessonId){if(!m)return missing();if(!unlocked(m.id))return locked(m);const l=lessonBy(lessonId),key=m.optional?`11-${l?.id}`:m.id,p=m.project,r=state.rubrics[key]||{scores:[0,0,0,0],evidence:''};return `<div class="page-intro"><div class="eyebrow">${m.optional?'OPTIONAL LAB':'MODULE '+m.id+' PROJECT'}</div><h1>${esc(m.optional&&l?l.title:p.title)}</h1><p>${m.optional&&l?esc(l.task):esc(p.dataset)}</p></div><div class="two-col"><section class="panel tint"><h2>Your brief</h2><p>${esc(m.optional&&l?l.walk:p.plan)}</p><h3>Required deliverables</h3><p>${esc(m.optional&&l?l.solution:p.deliverables)}</p></section><section class="panel"><h2>Get the data</h2><p class="small-copy">${esc(p.access)}</p><a class="text-link" href="${p.url}" target="_blank" rel="noopener">Dataset / documentation ↗</a>${[3,10].includes(m.id)?`<p style="margin-top:20px"><a class="btn light small" href="downloads/${m.id===3?'flawed-workflow.py':'diagnosis-mission.py'}" download>Download repair exercise</a></p>`:''}<p class="small-copy" style="margin-top:20px">Check the source’s current licence and access terms. Dataset names and versions must be recorded in your submission.</p></section></div><h2 style="margin-top:32px">Show your work</h2><p class="small-copy">Keep your notebook on your computer or in your repository. Paste its URL and a short evidence note below. This website does not upload or execute your project.</p><label class="sr-only" for="project-evidence">Project evidence and submission reference</label><textarea id="project-evidence" class="project-evidence" placeholder="Notebook link, reproduction command, results, and what you learned…">${esc(r.evidence)}</textarea><h2 style="margin-top:28px">Review your project</h2><p class="small-copy">This is an honest self-review, not independent grading. 0 = missing, 1 = incomplete, 2 = meets the criterion, 3 = strong evidence. A pass needs at least 2 on every criterion.</p><form id="rubric-form" data-key="${key}"><div class="table-scroll"><table class="rubric"><thead><tr><th>Criterion</th><th>What to check</th><th>Your score</th></tr></thead><tbody>${criteria.map(([title,description],i)=>`<tr><th scope="row">${title}</th><td>${description}</td><td><label class="sr-only" for="rubric-${i}">${title} score</label><select id="rubric-${i}" name="r${i}">${[0,1,2,3].map(n=>`<option value="${n}" ${r.scores[i]===n?'selected':''}>${n} / 3</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="tools-row"><button class="btn" type="submit">Save project review</button><a class="btn light" href="#module/${m.id}">Back to module</a></div><div id="project-result" role="status">${projectPass(key)?'<div class="completion-box">✓ Project self-review passed.</div>':''}</div></form>`;}
function shuffled(array){const a=[...array];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function testBank(m,lessonId){if(m.id===10)return course.modules.filter(x=>x.id<10).flatMap(x=>x.questions);if(m.id===11)return m.questions.filter(q=>q.chapter===Number(lessonId));return m.questions;}
function testKey(m,lessonId){return m.id===11?`11-${lessonId}`:String(m.id);}
function testPage(m,lessonId){if(!m)return missing();if(!unlocked(m.id))return locked(m);const key=testKey(m,lessonId),result=state.tests[key],count=m.id===10?40:m.id===11?5:20;
if(activeTest?.key===key&&!activeTest.submitted)return testForm(m);
if(result)return `<div class="page-intro"><div class="eyebrow">YOUR CHECK-IN RESULTS</div><h1>A little feedback.<br>A clearer next step.</h1></div><div class="test-result ${result.score>=80?'':'fail'}"><strong>${result.score}%</strong><p>${result.correct} of ${result.total} correct. ${result.confirmed===false?'Objective answers marked. Score the written answers below to finalize this attempt.':result.score>=80?'Test passed. Complete your project self-review to pass the module.':'80% is the pass mark. Review the explanations and revisit the linked lessons.'}</p><button class="btn" data-action="start-test" data-module="${m.id}" data-lesson="${lessonId||''}">Try a fresh selection</button></div><p class="small-copy">Self-study checks in this browser. Results are not a proctored credential. Retakes select and shuffle questions from the module’s question bank; some concepts may recur.</p>${(result.review||[]).map((q,i)=>questionHTML(q,i,'review',{answers:result.answers,written:result.written})).join('')}<a class="btn light" href="#module/${m.id}">Back to module</a>`;
return `<div class="page-intro"><div class="eyebrow">${m.id===10?'FINAL TEST':m.optional?'OPTIONAL QUIZ':'MODULE '+m.id+' TEST'}</div><h1>Let’s see what stuck.</h1><p>${count} questions on the ideas you just explored. Knowledge, code output, reasoning, and debugging. You need 80% to pass.</p></div><section class="panel tint"><h2>Before you begin</h2><p>${m.optional?'This optional five-question quiz has no countdown.':'You have 60 minutes. The timer continues if you leave or refresh, and an expired attempt is submitted when you return.'} Answers and explanations appear after submission. Core tests contain 8 knowledge, 6 output, 4 debugging and 2 written questions; the written answers use a disclosed self-review score.</p><p>These checks support self-study. Project quality is reviewed separately using a rubric.</p><button class="btn" data-action="start-test" data-module="${m.id}" data-lesson="${lessonId||''}">Start ${count}-question ${m.optional?'quiz':'test'}</button></section>`;}
function testForm(m){return `<div class="page-intro"><div class="eyebrow">${m.optional?'OPTIONAL QUIZ':'MODULE '+m.id+' TEST'}</div><h1>You’ve got this.</h1></div><div class="test-toolbar"><span>${activeTest.questions.length} questions · 80% to pass</span><span class="timer" id="timer">${m.optional?'No timer':'60:00'}</span></div><form id="module-test">${activeTest.questions.map((q,i)=>questionHTML(q,i,'tq',null)).join('')}<button class="btn" type="submit">Submit my answers</button><p class="small-copy" style="margin-top:18px">Unanswered questions count as incorrect. Your answers are saved as you select them.</p></form>`;}
function persistAttempt(){try{sessionStorage.setItem('studio-active-test',JSON.stringify(activeTest));}catch{toast('This browser cannot preserve an unfinished test. Stay on this page.');}}
function startTest(m,lessonId){const key=testKey(m,lessonId);const count=m.id===10?40:m.id===11?5:20;const bank=testBank(m,lessonId);const quotas=m.id===10?[['Knowledge',16],['Predict the output',12],['Debugging',8],['Written explanation',4]]:m.id===11?null:[['Knowledge',8],['Predict the output',6],['Debugging',4],['Written explanation',2]];let picked=quotas?quotas.flatMap(([type,n])=>shuffled(bank.filter(q=>q.type===type)).slice(0,n)):shuffled(bank.filter(q=>q.type!=='Written explanation')).slice(0,count);let selected=shuffled(picked).map(q=>{if(q.type==='Written explanation')return q;const options=shuffled(q.options.map((text,i)=>({text,correct:i===q.correct})));return {...q,options:options.map(o=>o.text),correct:options.findIndex(o=>o.correct)};});activeTest={key,module:m.id,lesson:lessonId||null,questions:selected,answers:{},deadline:m.optional?null:Date.now()+60*60*1000,submitted:false};state.attempts[key]=(state.attempts[key]||0)+1;save();persistAttempt();render();}
function submitTest(expired=false){if(!activeTest||activeTest.submitted)return;const correct=activeTest.questions.filter((q,i)=>q.type!=='Written explanation'&&activeTest.answers[i]===q.correct).length;const total=activeTest.questions.length;const score=Math.round(correct/total*100);state.tests[activeTest.key]={score,correct,total,answers:activeTest.answers,review:activeTest.questions,date:new Date().toISOString(),written:{},confirmed:!activeTest.questions.some(q=>q.type==='Written explanation')};activeTest.submitted=true;save();persistAttempt();toast(expired?'Time’s up. Your saved answers were submitted.':'Your objective answers are marked. Review all feedback, including written-answer self-scores.');render();}
function startClock(){clearInterval(timer);if(!activeTest||activeTest.submitted||!activeTest.deadline)return;const tick=()=>{const remain=activeTest.deadline-Date.now();if(remain<=0){clearInterval(timer);submitTest(true);return;}const el=$('#timer');if(el){const sec=Math.ceil(remain/1000);el.textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;}};tick();timer=setInterval(tick,1000);}
function challenge(){const ready=Array.from({length:10},(_,i)=>i+1).every(modulePass);return `<div class="page-intro"><div class="eyebrow">YOUR 14-DAY BUILDING CHALLENGE</div><h1>Turn “I get it”<br>into “I built it.”</h1><p>One bounded project a day. Two to three focused hours. Begins after Chapter 38 and the core module gates.</p><span class="pill ${ready?'':'yellow'}">${ready?'✦ Challenge unlocked':'Preview open · completion unlocks after the core course'}</span></div><div class="challenge-grid">${course.challenge.map(d=>`<section class="challenge-card ${state.days.includes(d.day)?'done':''}"><span class="challenge-day">DAY ${String(d.day).padStart(2,'0')} · 2–3 HOURS</span><h3>${esc(d.title)}</h3><p>${esc(d.brief)}</p><p><strong>Deliver:</strong> reproducible code, relevant evaluation, a short findings note, and limitations. For exploratory work, explain what its metrics do and do not establish.</p><p class="small-copy">Reuses Chapters ${esc(d.chapters)}. Use the four project criteria; aim for at least 2 on each.</p><button class="btn light small" data-action="challenge" data-id="${d.day}" ${!ready?'disabled':''}>${state.days.includes(d.day)?'✓ Completed · undo':'Mark project complete'}</button></section>`).join('')}</div>`;}
function glossary(query=''){const entries=course.lessons.flatMap(l=>l.terms.map(t=>({...t,chapter:l.id}))).sort((a,b)=>a.term.localeCompare(b.term));const filtered=entries.filter(e=>(e.term+' '+e.meaning).toLowerCase().includes(query.toLowerCase()));return `<div class="page-intro"><div class="eyebrow">WORDS, WITHOUT THE MYSTERY</div><h1>Your growing glossary.</h1><p>A plain-language definition and a way back to the lesson that explains it.</p></div><label class="sr-only" for="glossary-query">Filter glossary</label><input id="glossary-query" class="glossary-search" value="${esc(query)}" placeholder="Find a term…"><div id="glossary-entries">${glossaryEntries(filtered)}</div>`;}
function glossaryEntries(entries){return entries.length?entries.map(e=>`<div class="glossary-item"><strong>${esc(e.term)}</strong><p>${esc(e.meaning)}</p><a class="text-link" href="#lesson/${e.chapter}">Chapter ${e.chapter}</a></div>`).join(''):'<div class="empty">No matching terms. Try another word.</div>';}
function resources(){return `<div class="page-intro"><div class="eyebrow">YOUR PRACTICE TOOLKIT</div><h1>Everything you need<br>to keep going.</h1><p>Run Python examples on your PC, in Jupyter, or in a compatible hosted notebook. This website shows executed examples and checks understanding; it does not run arbitrary Python in your browser.</p></div><div class="resource-list">${[['Practice notebooks','47 chapter notebooks with worked examples and exercise prompts.','downloads/practice-notebooks.zip','Download notebooks'],['Course outline','A downloadable module and chapter index generated from this edition. Your original curriculum attachment is not published here.','downloads/course-outline.md','Download course outline'],['Core environment','Exact package versions used for the executed lesson examples. Python '+course.environment.Python+'.','downloads/requirements.txt','Download requirements'],['Optional dependencies','Extra packages for resampling, external boosting, and the local API lab. Install after the core environment.','downloads/requirements-optional.txt','Download optional requirements'],['Executed-example record','Execution results and environment information for the examples in this edition.','downloads/execution-report.json','Download execution record'],['Repair mission','A deliberately flawed workflow. Identify and repair the leaks before trusting its scores.','downloads/flawed-workflow.py','Download flawed workflow']].map(([title,description,url,label])=>`<section class="resource-card"><span class="module-symbol">▤</span><h3>${title}</h3><p>${description}</p><a class="text-link" href="${url}" ${url.endsWith('.pdf')?'target="_blank" rel="noopener"':'download'}>${label}</a></section>`).join('')}</div><div class="section-head"><h2>Your progress travels with you</h2></div><section class="panel tint"><p>Progress, quiz results, project self-reviews, and notes stay in this browser. Export a backup, then import it on another device. There is no account sync or notebook auto-grader in this edition.</p><div class="tools-row"><button class="btn" data-action="export">Export my progress</button><button class="btn light" data-action="import">Import progress</button><button class="btn light" data-action="reset">Reset this browser’s progress</button></div></section><h2 style="margin-top:30px">The frozen lesson environment</h2><div class="table-scroll"><table class="rubric"><thead><tr><th>Tool</th><th>Version</th></tr></thead><tbody>${Object.entries(course.environment).map(([name,version])=>`<tr><td>${esc(name)}</td><td>${esc(version)}</td></tr>`).join('')}</tbody></table></div><div class="callout yellow"><strong>Course status and estimates</strong><p>This is the first working self-study edition. Its lesson examples have been executed, but it has not been timed with beginner pilot readers. Core estimates are 112–165 hours, extensions 44–71, and the separate challenge 28–42. Core tests use knowledge, code-output, debugging and written explanation questions. Objective items are automatic; written answers and projects use disclosed self-review. Independent written grading is not provided.</p></div><h2>Official references</h2><p><a class="text-link" href="https://scikit-learn.org/1.8/user_guide.html" target="_blank" rel="noopener">scikit-learn 1.8 User Guide ↗</a></p><p><a class="text-link" href="https://scikit-learn.org/1.8/common_pitfalls.html" target="_blank" rel="noopener">Common pitfalls and recommended practices ↗</a></p><p><a class="text-link" href="https://imbalanced-learn.org/stable/common_pitfalls.html" target="_blank" rel="noopener">Resampling pitfalls ↗</a></p><p><a class="text-link" href="https://xgboost.readthedocs.io/en/release_3.1.0/python/sklearn_estimator.html" target="_blank" rel="noopener">XGBoost estimator interface ↗</a></p><p class="small-copy">Dataset links appear in each project brief. Verify provider terms before downloading or redistributing data.</p>`;}
function missing(){return '<div class="page-intro"><h1>That page wandered off.</h1><p>Choose a lesson from the course map.</p><a class="btn" href="#curriculum">Open course map</a></div>';}
function render(){if(!course)return;const [route='home',id,sub]=location.hash.slice(1).split('/');let html,nav=route;
if(route==='home'||!route)html=overview();else if(route==='curriculum')html=curriculum();else if(route==='module'){html=modulePage(moduleBy(id));nav='curriculum';}else if(route==='lesson'){html=lessonPage(lessonBy(id));nav='curriculum';}else if(route==='test'){html=testPage(moduleBy(id),sub);nav='curriculum';}else if(route==='project'){html=projectPage(moduleBy(id),sub);nav='curriculum';}else if(route==='challenge')html=challenge();else if(route==='glossary')html=glossary(decodeURIComponent(id||''));else if(route==='resources')html=resources();else html=missing();
$('#main').innerHTML=html;sidebar(nav);$('#breadcrumb').innerHTML=`Your learning space <span>/</span> ${esc(route==='lesson'?'Chapter '+id:route==='module'?'Module '+id:route==='home'?'Overview':route.charAt(0).toUpperCase()+route.slice(1))}`;document.title=(route==='lesson'?(lessonBy(id)?.title||'Lesson'):'Your learning space')+' · Scikit-learn Studio';$('#sidebar').classList.remove('open');$('#shade').classList.remove('open');startClock();if(activeTest&&!activeTest.submitted&&route==='test'&&activeTest.key===testKey(moduleBy(id),sub)){Object.entries(activeTest.answers).forEach(([i,v])=>{const el=$(`input[name="tq${i}"][value="${v}"]`);if(el)el.checked=true;const area=$(`textarea[name="tq${i}"]`);if(area)area.value=v;});}}
function search(query){const q=query.trim().toLowerCase();const results=course.lessons.filter(l=>(l.title+' '+l.terms.map(t=>t.term).join(' ')).toLowerCase().includes(q));$('#search-results').innerHTML=results.slice(0,18).map(l=>`<a class="search-result" href="#lesson/${l.id}"><strong>${esc(l.title)}</strong><small>Chapter ${l.id} · Module ${l.module} ${unlocked(l.module)?'':'· locked'}</small></a>`).join('')||'<p class="empty">No matches. Try a shorter term.</p>';}
function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';search('');$('#search-input').focus();}
document.addEventListener('click',async e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id);switch(b.dataset.action){case'copy':{const text=lessonBy(id).code;try{await navigator.clipboard.writeText(text);toast('Code copied. Your next experiment awaits.');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();try{document.execCommand('copy');toast('Code copied.');}catch{toast('Select and copy the code from its box.');}area.remove();}break;}case'bookmark':state.last=id;save();toast('Your place is saved in this browser.');break;case'print':window.print();break;case'complete':if(!state.reviewed.includes(id)){toast('Complete the understanding check first. You can retry it.');return;}if(![...document.querySelectorAll('.completion-check')].every(x=>x.checked)){toast('Check the three completion statements after your practice.');return;}if(!lessonDone(id))state.completed.push(id);save();toast('A small win, well earned. Lesson completed!');b.textContent='✓ Lesson completed';sidebar('curriculum');break;case'start-test':if(activeTest&&!activeTest.submitted&&activeTest.key!==testKey(moduleBy(b.dataset.module),b.dataset.lesson)&&!confirm('Replace your unfinished test? Its current answers will be discarded.'))return;startTest(moduleBy(b.dataset.module),b.dataset.lesson);break;case'challenge':if(!Array.from({length:10},(_,i)=>i+1).every(modulePass))return;state.days=state.days.includes(id)?state.days.filter(n=>n!==id):[...state.days,id];save();render();break;case'export':download('scikit-studio-progress.json',JSON.stringify(state,null,2));break;case'import':$('#import-progress').click();break;case'reset':if(confirm('Reset all saved progress, notes, tests, and reviews in this browser? Export a backup first if you want to keep them.')){state=fresh();activeTest=null;try{sessionStorage.removeItem('studio-active-test');}catch{}save();render();toast('A fresh start.');}break;}});
document.addEventListener('submit',e=>{if(e.target.id==='chapter-quiz'){e.preventDefault();const id=Number(e.target.dataset.lesson),qs=getQuiz(lessonBy(id));let correct=0;qs.forEach((q,i)=>{const chosen=e.target.querySelector(`input[name="cq${i}"]:checked`);const right=chosen&&Number(chosen.value)===q.correct;if(right)correct++;$(`#feedback-cq${i}`).innerHTML=`<div class="feedback ${right?'':'bad'}">${right?'✓ Correct.':'Revisit this idea.'} ${esc(q.explanation)}</div>`;});if(correct===qs.length&&!state.reviewed.includes(id)){state.reviewed.push(id);save();}$('#chapter-result').innerHTML=`<div class="feedback ${correct===qs.length?'':'bad'}">${correct}/${qs.length} correct. ${correct===qs.length?'Ready to reflect and complete the lesson.':'Read the explanations and try again.'}</div>`;}else if(e.target.id==='module-test'){e.preventDefault();submitTest();window.scrollTo({top:0,behavior:'smooth'});}else if(e.target.id==='rubric-form'){e.preventDefault();const key=e.target.dataset.key,scores=[0,1,2,3].map(i=>Number(e.target.elements['r'+i].value));const evidence=$('#project-evidence').value.trim();if(evidence.length<30){toast('Add an evidence note or submission reference of at least 30 characters.');$('#project-evidence').focus();return;}state.rubrics[key]={scores,evidence,date:new Date().toISOString()};save();$('#project-result').innerHTML=`<div class="${projectPass(key)?'completion-box':'callout yellow'}">${projectPass(key)?'✓ Self-review passed.':'Review saved. Each criterion needs at least 2 to pass.'} ${modulePass(Number(key))?'Test and project passed; the next core module is unlocked.':''}</div>`;sidebar('curriculum');toast('Project review saved.');}});
document.addEventListener('input',e=>{if(e.target.id==='lesson-notes'){state.notes[e.target.dataset.id]=e.target.value;save();}if(e.target.name?.startsWith('tq')&&e.target.tagName==='TEXTAREA'&&activeTest&&!activeTest.submitted){activeTest.answers[e.target.name.slice(2)]=e.target.value;persistAttempt();}if(e.target.id==='search-input')search(e.target.value);if(e.target.id==='glossary-query'){const q=e.target.value.toLowerCase();const entries=course.lessons.flatMap(l=>l.terms.map(t=>({...t,chapter:l.id}))).filter(t=>(t.term+' '+t.meaning).toLowerCase().includes(q)).sort((a,b)=>a.term.localeCompare(b.term));$('#glossary-entries').innerHTML=glossaryEntries(entries);}});
document.addEventListener('change',e=>{if(e.target.dataset.writtenScore!==undefined){const parts=location.hash.slice(1).split('/');const key=testKey(moduleBy(parts[1]),parts[2]);const result=state.tests[key];if(!result)return;const index=e.target.dataset.writtenScore;if(e.target.value==='')delete result.written[index];else{if(e.target.value==='1'&&String(result.answers[index]||'').trim().length<20){toast('A correct self-score needs an actual written explanation. Retake to add it.');e.target.value='';return;}result.written[index]=Number(e.target.value);}const indices=result.review.map((q,i)=>q.type==='Written explanation'?i:null).filter(i=>i!==null);result.confirmed=indices.every(i=>result.written[i]!==undefined);result.correct=result.review.filter((q,i)=>q.type!=='Written explanation'&&result.answers[i]===q.correct).length+Object.values(result.written).reduce((a,b)=>a+b,0);result.score=Math.round(result.correct/result.total*100);save();render();return;}if(e.target.name?.startsWith('tq')&&activeTest&&!activeTest.submitted){activeTest.answers[e.target.name.slice(2)]=Number(e.target.value);persistAttempt();}});
$('#import-progress').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.edition!==1||!Array.isArray(data.completed)||!Array.isArray(data.reviewed)||!Array.isArray(data.days)||!data.tests||!data.rubrics||!data.notes||typeof data.notes!=='object')throw Error('Invalid progress file');if(!confirm('Replace this browser’s progress with the imported backup?'))return;state={...fresh(),...data,completed:data.completed.filter(n=>Number.isInteger(n)&&n>0&&n<=47),reviewed:data.reviewed.filter(n=>Number.isInteger(n)&&n>0&&n<=47),days:data.days.filter(n=>Number.isInteger(n)&&n>=1&&n<=14)};activeTest=null;try{sessionStorage.removeItem('studio-active-test');}catch{}save();render();toast('Your progress is back. Welcome!');}catch{toast('That file could not be imported. Choose an exported Studio progress JSON.');}e.target.value='';});
$('#open-menu').onclick=()=>{$('#sidebar').classList.add('open');$('#shade').classList.add('open');};const closeMenu=()=>{$('#sidebar').classList.remove('open');$('#shade').classList.remove('open');};$('#close-menu').onclick=closeMenu;$('#shade').onclick=closeMenu;$('#open-search').onclick=openSearch;$('#close-search').onclick=()=>$('#search-dialog').close();$('#search-dialog').addEventListener('click',e=>{if(e.target.closest('.search-result'))$('#search-dialog').close();});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();}if(e.key==='Escape')closeMenu();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
fetch('course.json').then(r=>{if(!r.ok)throw Error('Course data unavailable');return r.json();}).then(data=>{course=data;try{const t=JSON.parse(sessionStorage.getItem('studio-active-test')||'null');if(t&&!t.submitted&&Array.isArray(t.questions))activeTest=t;}catch{}render();if(!storageAvailable)toast('Storage unavailable. Export progress before leaving.');}).catch(()=>{$('#main').innerHTML='<div class="error-message"><h1>The course could not load.</h1><p>Check your connection and reload. For local use, serve the dist folder with a web server instead of opening index.html directly.</p><button class="btn" onclick="location.reload()">Try again</button></div>';});
})();
